"use client";

import { Button as Primitive } from "@base-ui/react/button";
import { AnimatePresence, motion } from "motion/react";
import type { ComponentProps } from "react";

import { useClipboard } from "@/hooks/use-clipboard";
import { useReducedMotion } from "@/hooks/use-reduced-motion";
import { Icon } from "@/lib/icon-context";
import { motionTransition, spring } from "@/lib/motion";
import { useShape } from "@/lib/shape-context";
import { useSize } from "@/lib/size-context";
import type { SizeVariant } from "@/lib/size-context";
import { cn } from "@/lib/utils";

export interface InputCopyProps extends Omit<
  ComponentProps<"div">,
  "onCopy" | "children"
> {
  value: string;
  label?: string;
  disabled?: boolean;
  size?: SizeVariant;
  variant?: "icon" | "button";
  align?: "left" | "right";
  onCopy?: () => void;
}
export const InputCopy = ({
  value,
  label,
  disabled,
  size,
  variant = "icon",
  align = "right",
  onCopy,
  className,
  ...props
}: InputCopyProps) => {
  const { copy, copied, error } = useClipboard();
  const sizes = useSize(size);
  const shape = useShape();
  const reduced = useReducedMotion();
  const copyStatus = copied ? "Copied" : "Copy";
  const status = error ? "Copy failed" : copyStatus;
  const copyIcon = copied ? "check" : "copy";
  const successAnnouncement = copied ? "Copied to clipboard" : "";
  return (
    <div className={cn("flex min-w-0 flex-col gap-1", className)} {...props}>
      {label && (
        <span className={cn("text-muted-foreground", sizes.text)}>{label}</span>
      )}
      <Primitive
        disabled={disabled}
        aria-label={`${status}${label ? ` ${label}` : " to clipboard"}`}
        onClick={async () => {
          if (await copy(value)) {
            onCopy?.();
          }
        }}
        className={cn(
          "group flex w-full min-w-0 items-center text-left outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50",
          sizes.control,
          sizes.text,
          sizes.px,
          sizes.gap,
          shape,
          align === "left" && "flex-row-reverse"
        )}
      >
        <span className="min-w-0 flex-1 truncate font-mono">
          <span className="group-hover:bg-[#6b97ff]/20">{value}</span>
        </span>
        <span
          className={cn(
            "flex shrink-0 items-center gap-1.5",
            sizes.iconClass,
            error && "text-destructive"
          )}
        >
          <AnimatePresence mode="wait" initial={false}>
            <motion.span
              key={status}
              initial={{ opacity: 0, scale: 0.8 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.8 }}
              transition={motionTransition(spring.fast, reduced)}
              className="flex"
            >
              <Icon name={error ? "close" : copyIcon} />
            </motion.span>
          </AnimatePresence>
          {variant === "button" && <span className="min-w-12">{status}</span>}
        </span>
      </Primitive>
      <span role="status" className="sr-only">
        {error ? "Unable to copy. Try again." : successAnnouncement}
      </span>
    </div>
  );
};

"use client";
import { useCallback, useEffect, useRef, useState } from "react";

export const useClipboard = ({ timeout = 2000 }: { timeout?: number } = {}) => {
  const [copied, setCopied] = useState(false);
  const [copyError, setError] = useState<Error | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const request = useRef(0);
  useEffect(
    () => () => {
      request.current += 1;
      if (timer.current) {
        clearTimeout(timer.current);
      }
    },
    []
  );
  const copy = useCallback(
    async (text: string) => {
      request.current += 1;
      const id = request.current;
      if (timer.current) {
        clearTimeout(timer.current);
      }
      setCopied(false);
      setError(null);
      try {
        await navigator.clipboard.writeText(text);
        if (id !== request.current) {
          return false;
        }
        setCopied(true);
        if (timeout > 0) {
          timer.current = setTimeout(() => setCopied(false), timeout);
        }
        return true;
      } catch (error) {
        if (id === request.current) {
          setError(
            error instanceof Error
              ? error
              : new Error("Unable to copy to the clipboard.")
          );
        }
        return false;
      }
    },
    [timeout]
  );
  return { copied, copy, error: copyError };
};

import { useEffect, useState } from "react";

export const useMediaQuery = (query: string) => {
  const [value, setValue] = useState(false);

  useEffect(() => {
    const onChange = (event: MediaQueryListEvent) => {
      setValue(event.matches);
    };

    const result = matchMedia(query);
    result.addEventListener("change", onChange);
    setValue(result.matches);

    return () => result.removeEventListener("change", onChange);
  }, [query]);

  return value;
};

"use client";

import { useMediaQuery } from "@/hooks/use-media-query";

/** False during SSR and the first hydration render; subscribes after mounting. */
export const useReducedMotion = () =>
  useMediaQuery("(prefers-reduced-motion: reduce)");

"use client";

import {
  Check,
  ChevronDown,
  ChevronRight,
  Copy,
  LoaderCircle,
  Search,
  X,
} from "lucide-react";
import { createContext, useContext, useMemo } from "react";
import type { ComponentType, ReactNode, SVGProps } from "react";

export type IconProps = SVGProps<SVGSVGElement> & {
  size?: number;
  strokeWidth?: number;
};
export type IconComponent = ComponentType<IconProps>;
export const defaultIcons = {
  check: Check,
  "chevron-down": ChevronDown,
  "chevron-right": ChevronRight,
  close: X,
  copy: Copy,
  loading: LoaderCircle,
  search: Search,
} satisfies Record<string, IconComponent>;
export type IconName = keyof typeof defaultIcons;
const IconContext =
  createContext<Record<IconName, IconComponent>>(defaultIcons);
export const IconProvider = ({
  icons,
  children,
}: {
  icons: Partial<Record<IconName, IconComponent>>;
  children: ReactNode;
}) => {
  const parent = useContext(IconContext);
  const value = useMemo(() => ({ ...parent, ...icons }), [parent, icons]);
  return <IconContext.Provider value={value}>{children}</IconContext.Provider>;
};
export const Icon = ({ name, ...props }: IconProps & { name: IconName }) => {
  const Component = useContext(IconContext)[name];
  return <Component aria-hidden="true" focusable="false" {...props} />;
};

import type { Transition } from "motion/react";

// Base UI owns presence; CSS consumers use the same timing ladder as Motion.
export const motionClasses = {
  moderate:
    "duration-(--motion-moderate) data-[state=closed]:duration-(--motion-exit-moderate) motion-reduce:animate-none",
  slow: "duration-(--motion-slow) data-[state=closed]:duration-(--motion-exit-slow) motion-reduce:animate-none",
};

// Fluid Functionalism's timing ladder: quick feedback, precise panels, larger moves.
export const spring = {
  fast: { bounce: 0, duration: 0.08, exit: { duration: 0.06 }, type: "spring" },
  moderate: {
    bounce: 0,
    duration: 0.16,
    exit: { duration: 0.12 },
    type: "spring",
  },
  slow: {
    bounce: 0.12,
    duration: 0.24,
    exit: { duration: 0.16 },
    type: "spring",
  },
} as const;

export const motionPresets = {
  activeIndicator: spring.moderate,
  enter: {
    animate: { opacity: 1, scale: 1 },
    initial: { opacity: 0, scale: 0.95 },
    transition: spring.moderate,
  },
  exit: { opacity: 0, scale: 0.95, transition: spring.moderate.exit },
  fade: { duration: spring.fast.duration },
  hover: spring.fast,
  layout: spring.moderate,
  snap: { duration: 0 },
} satisfies Record<string, unknown>;

export const motionTransition = (
  transition: Transition,
  reduced: boolean
): Transition =>
  reduced ? { duration: 0, opacity: motionPresets.fade } : transition;

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type ShapeVariant = "rounded" | "pill";
const ShapeContext = createContext<ShapeVariant>("rounded");
export const shapeMap = {
  pill: "rounded-[20px]",
  rounded: "rounded-lg",
} as const;
export const ShapeProvider = ({
  shape,
  children,
}: {
  shape: ShapeVariant;
  children: ReactNode;
}) => <ShapeContext.Provider value={shape}>{children}</ShapeContext.Provider>;
export const useShape = (override?: ShapeVariant) => {
  const inherited = useContext(ShapeContext);
  return shapeMap[override ?? inherited];
};

"use client";

import { createContext, useContext } from "react";
import type { ReactNode } from "react";

export type SizeVariant = "default" | "compact";
const SizeContext = createContext<SizeVariant>("default");
export const sizeMap = {
  compact: {
    control: "h-7",
    controlHeight: 28,
    gap: "gap-1",
    icon: 14,
    iconClass: "[&_svg:not([class*='size-'])]:size-3.5",
    px: "px-2.5",
    text: "text-xs",
    variant: "compact",
  },
  default: {
    control: "h-9",
    controlHeight: 36,
    gap: "gap-2",
    icon: 16,
    iconClass: "[&_svg:not([class*='size-'])]:size-4",
    px: "px-3",
    text: "text-[13px]",
    variant: "default",
  },
} as const;
export const SizeProvider = ({
  size,
  children,
}: {
  size: SizeVariant;
  children: ReactNode;
}) => <SizeContext.Provider value={size}>{children}</SizeContext.Provider>;
export const useSizeVariant = (override?: SizeVariant) => {
  const inherited = useContext(SizeContext);
  return override ?? inherited;
};
export const useSize = (override?: SizeVariant) =>
  sizeMap[useSizeVariant(override)];
